public static RetailPricingSimulatorSalesTransaction find(ConfigName _name, boolean _forUpdate = false)
{
    RetailPricingSimulatorSalesTransaction pricingSimulatorSalesTransaction;

    if (_name)
    {
        if (_forUpdate)
        {
            pricingSimulatorSalesTransaction.selectForUpdate(_forUpdate);
        }

        select firstonly pricingSimulatorSalesTransaction
            where pricingSimulatorSalesTransaction.SimulationName == _name;
    }

    return pricingSimulatorSalesTransaction;
}
